mapper.select:
select distinct t1.id, t1.name, t1.product_id, t1.active_version, t1.product_category_id, t3.name as productName, t3.specification, t3.merge_code as mergeCode, bm_process_dashboard_config.process_version as dashboard_config_version from bm_process t1 join bm_resource_permission t2 on t1.id = t2.resource_id join bm_material t3 on t1.product_id = t3.id left join bm_process_dashboard_config on t1.id = bm_process_dashboard_config.process_id and bm_process_dashboard_config.is_deleted = 0 where t1.is_deleted = 0 and t2.dept_id in
#{item}
and t1.name like concat('%',#{name},'%')
and t1.product_id = #{productId}
and t1.product_category_id in
#{item}
order by t1.create_time desc

select distinct t1.id, t1.name, t1.product_id, t1.active_version from bm_process t1 join bm_resource_permission t2 on t1.id = t2.resource_id where t1.is_deleted = 0
and t1.product_id in
#{item}
and t2.dept_id in
#{item}
